function plot_q4
root=fileparts(fileparts(mfilename('fullpath')));d=jsondecode(fileread(fullfile(root,'results','q4_report.json')));out=fullfile(root,'paper','figures');if ~isfolder(out),mkdir(out);end
set(groot,'defaultAxesFontName','Microsoft YaHei','defaultTextFontName','Microsoft YaHei');names=string({d.comparison.variant});cost=[d.comparison.total_cost]/1e4;em=[d.comparison.emergency_total]/1e4;
f=figure('Visible','off','Color','w','Position',[100 100 900 700]);tiledlayout(2,1);nexttile;barh(cost,'FaceColor',[.85 .85 .85],'EdgeColor','k');set(gca,'YTick',1:numel(names),'YTickLabel',names,'YDir','reverse');xlabel('总费用 / 万元');grid on;nexttile;barh(em,'FaceColor',[.55 .55 .55],'EdgeColor','k');set(gca,'YTick',1:numel(names),'YTickLabel',names,'YDir','reverse');xlabel('紧急购电量 / 万kWh');grid on;saveall(f,out,'q4_compare');
for k=1:min(4,numel(d.selected)),s=d.selected(k);x=(0:numel(s.soc_kwh)-2)/6;f=figure('Visible','off','Color','w','Position',[100 100 900 900]);tiledlayout(4,1);nexttile;plot(x,s.price_actual,'k-',x,s.forecast_price,'k--');ylabel('电价');legend('实际','预报');grid on;nexttile;plot(x,s.soc_kwh,'k-');ylabel('SOC / kWh');grid on;nexttile;stairs(x,s.charge_kwh,'k-');hold on;stairs(x,-s.discharge_kwh,'k--');ylabel('充正/放负');grid on;nexttile;stairs(x,s.emergency_kwh,'k-');ylabel('紧急购电');xlabel('时刻 / h');grid on;saveall(f,out,['q4_day_' strrep(s.date,'-','')]);end
end
function saveall(f,out,n),exportgraphics(f,fullfile(out,[n '.pdf']),'ContentType','vector');exportgraphics(f,fullfile(out,[n '.png']),'Resolution',300);savefig(f,fullfile(out,[n '.fig']));close(f);end
